long countAtMostK(String s, int k) {
    long count = 0;
    for (int i = 0; i < s.length(); i++) {
        for (int j = i; j < s.length(); j++) {
            Set<Character> kinds = new HashSet<>();
            for (int t = i; t <= j; t++) kinds.add(s.charAt(t));   // the kinds in s[i..j]
            if (kinds.size() <= k) count++;
        }
    }
    return count;
}

