function countAtMostK(s, k) {
  const freq = new Map();                            // char -> count inside the window
  let left = 0, count = 0;
  for (let right = 0; right < s.length; right++) {
    freq.set(s[right], (freq.get(s[right]) ?? 0) + 1);
    while (freq.size > k) {                           // too many kinds: shrink from the left
      const out = s[left++];
      freq.set(out, freq.get(out) - 1);
      if (freq.get(out) === 0) freq.delete(out);
    }
    count += right - left + 1;                        // every start from left to right works
  }
  return count;
}

long countAtMostK(String s, int k) {
    Map<Character, Integer> freq = new HashMap<>();     // char -> count inside the window
    int left = 0;
    long count = 0;
    for (int right = 0; right < s.length(); right++) {
        freq.merge(s.charAt(right), 1, Integer::sum);
        while (freq.size() > k) {                        // too many kinds: shrink from the left
            char out = s.charAt(left++);
            if (freq.merge(out, -1, Integer::sum) == 0) freq.remove(out);
        }
        count += right - left + 1;                       // every start from left to right works
    }
    return count;
}

long long countAtMostK(string s, int k) {
    unordered_map<char, int> freq;                     // char -> count inside the window
    int left = 0;
    long long count = 0;
    for (int right = 0; right < (int)s.size(); right++) {
        freq[s[right]]++;
        while ((int)freq.size() > k) {                 // too many kinds: shrink from the left
            char out = s[left++];
            if (--freq[out] == 0) freq.erase(out);
        }
        count += right - left + 1;                     // every start from left to right works
    }
    return count;
}

