def at_most(s, k):
    freq = defaultdict(int)
    left = count = 0
    for right, ch in enumerate(s):
        freq[ch] += 1
        while len(freq) > k:
            out = s[left]
            left += 1
            freq[out] -= 1
            if freq[out] == 0:
                del freq[out]
        count += right - left + 1
    return count

